import { Component, inject } from '@angular/core';
import { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideBell,
  lucideChevronRight,
  lucideCrosshair,
  lucideLayoutDashboard,
  lucideMoon,
  lucideSearch,
  lucideSettings,
  lucideShieldAlert,
  lucideSun,
  lucideTarget,
  lucideUserPlus,
  lucideUsers,
} from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmInputImports } from '@spartan-ng/helm/input';
import { HlmSidebarImports } from '@spartan-ng/helm/sidebar';
import { HlmTooltipImports } from '@spartan-ng/helm/tooltip';
import { AppViewModel } from './app.view-model';

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmSidebarImports,
    HlmButtonImports,
    HlmInputImports,
    HlmTooltipImports,
    HlmAvatarImports,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideBell,
      lucideChevronRight,
      lucideCrosshair,
      lucideLayoutDashboard,
      lucideMoon,
      lucideSearch,
      lucideSettings,
      lucideShieldAlert,
      lucideSun,
      lucideTarget,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
}
<div hlmSidebarWrapper class="app">
  <hlm-sidebar>
    <div hlmSidebarHeader class="app__brand">
      <ng-icon name="lucideCrosshair" class="app__brand-icon" aria-hidden="true" />
      <span>Hero Ops Console</span>
    </div>

    <div hlmSidebarContent>
      <nav aria-label="Primary">
        <div hlmSidebarGroup>
          <div hlmSidebarGroupLabel>Operations</div>
          <div hlmSidebarGroupContent>
            <ul hlmSidebarMenu>
              @for (item of vm.navItems; track item.path) {
                <li hlmSidebarMenuItem>
                  <a
                    hlmSidebarMenuButton
                    [routerLink]="item.path"
                    routerLinkActive
                    #active="routerLinkActive"
                    [isActive]="active.isActive"
                  >
                    <ng-icon [name]="item.icon" aria-hidden="true" />
                    <span>{{ item.label }}</span>
                  </a>
                </li>
              }
            </ul>
          </div>
        </div>
      </nav>
    </div>

    <div hlmSidebarFooter class="app__footer">
      <p class="app__footer-note">Example data: demo console</p>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset class="app__main">
    <header class="app__topbar">
      <button hlmSidebarTrigger class="app__menu"></button>

      <nav aria-label="Breadcrumb" class="app__crumbs">
        <ol class="app__crumb-list">
          @for (crumb of vm.crumbs(); track $index; let last = $last) {
            <li class="app__crumb">
              @if (last || !crumb.path) {
                <span class="app__crumb-current" aria-current="page">{{ crumb.label }}</span>
              } @else {
                <a class="app__crumb-link" [routerLink]="crumb.path">{{ crumb.label }}</a>
